import{_ as t,c as n,o as i,ah as d}from"./chunks/framework.BjIn8lrq.js";const g=JSON.parse('{"title":"32. REST-API","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-c-entwicklungs-systemdokumentation/32-rest-api.md","filePath":"manual/teil-c-entwicklungs-systemdokumentation/32-rest-api.md"}'),r={name:"manual/teil-c-entwicklungs-systemdokumentation/32-rest-api.md"};function a(o,e,s,c,l,u){return i(),n("div",null,[...e[0]||(e[0]=[d(`<h1 id="_32-rest-api" tabindex="-1">32. REST-API <a class="header-anchor" href="#_32-rest-api" aria-label="Permalink to &quot;32. REST-API&quot;">​</a></h1><p>Dieses Kapitel beschreibt die Schnittstelle des Backends: wie sich ein Programm anmeldet, wie die Endpunkte aufgebaut sind, welche Rechte sie prüfen und wie sie antworten. Die Weboberfläche bezieht ihre Fachdaten ausschließlich über diese Schnittstelle; alles, was sie davon anzeigt, lässt sich auch direkt abrufen.</p><p>Die Schnittstelle liegt unter <code>https://&lt;API_DOMAIN&gt;/api/v1/</code>. Die Version steht im Pfad und wird über <code>NamespaceVersioning</code> von Django REST Framework ausgewertet; eine andere als <code>v1</code> gibt es nicht. Antworten sind JSON, sofern ein Endpunkt nicht ausdrücklich eine Datei liefert.</p><h2 id="_32-1-authentifizierung-jwt-cookies-token-rotation" tabindex="-1">32.1 Authentifizierung: JWT, Cookies, Token-Rotation <a class="header-anchor" href="#_32-1-authentifizierung-jwt-cookies-token-rotation" aria-label="Permalink to &quot;32.1 Authentifizierung: JWT, Cookies, Token-Rotation&quot;">​</a></h2><p>Die Schnittstelle kennt drei Arten der Anmeldung, je nach Gegenüber.</p><p><strong>Weboberfläche: JWT in Cookies.</strong> Die Anmeldung über <code>POST /api/v1/auth/login/</code> mit <code>username</code> und <code>password</code> (dj-rest-auth) setzt zwei Cookies:</p><table tabindex="0"><thead><tr><th>Cookie</th><th>Inhalt</th><th>Gültigkeit</th></tr></thead><tbody><tr><td><code>api-access-token</code></td><td>Zugangstoken</td><td>15 Minuten</td></tr><tr><td><code>api-refresh-token</code></td><td>Erneuerungstoken</td><td>7 Tage</td></tr></tbody></table><p>Beide sind <code>HttpOnly</code>, <code>Secure</code> und <code>SameSite=Lax</code>; im Browser kommt kein Skript an sie heran. Bei jeder Anfrage liest das Backend den Zugangstoken aus dem Cookie. Läuft er ab, holt <code>POST /api/v1/auth/token/refresh/</code> mit dem Erneuerungstoken ein neues Paar. Dabei wird auch der Erneuerungstoken ersetzt und der alte auf eine Sperrliste gesetzt (<code>ROTATE_REFRESH_TOKENS</code>, <code>BLACKLIST_AFTER_ROTATION</code>): Jeder Erneuerungstoken gilt genau einmal. Wer denselben Token zweimal verwendet, etwa aus zwei parallelen Prozessen, bekommt beim zweiten Mal 401. <code>POST /api/v1/auth/logout/</code> löscht die Cookies, <code>GET /api/v1/auth/user/</code> liefert das angemeldete Konto.</p><p>Damit die Cookies für alle Adressen einer Installation gelten, setzt die Middleware <code>CookieDomainMiddleware</code> ihre Domain auf <code>COOKIE_DOMAIN</code>, sofern <code>USE_COOKIE_DOMAIN_MIDDLEWARE</code> eingeschaltet ist. Wie die Weboberfläche die Tokens erneuert, beschreibt Abschnitt <a href="./33-frontend.html#_33-8-anmeldung-token-erneuerung-und-routenschutz-im-frontend">Anmeldung, Token-Erneuerung und Routenschutz im Frontend</a>.</p><p><strong>Andere Programme: JWT im Header.</strong> Für Anwendungen außerhalb des Browsers, die keine Cookies verwalten, gibt es eigene Endpunkte unter <code>/api/v1/auth/app/</code>:</p><ul><li><code>POST login/</code> mit <code>username</code> und <code>password</code> liefert die Tokens im Rumpf der Antwort statt in Cookies: <code>access</code>, <code>refresh</code>, die Ablaufzeitpunkte <code>access_expiration</code> und <code>refresh_expiration</code> als Unix-Zeit und das Konto unter <code>user</code>.</li><li><code>POST token/refresh/</code> mit <code>refresh</code> im Rumpf liefert ein neues Paar; auch hier gilt jeder Erneuerungstoken nur einmal.</li><li><code>POST logout/</code> mit <code>refresh</code> im Rumpf setzt den Erneuerungstoken auf die Sperrliste.</li></ul><p>Jede weitere Anfrage trägt den Zugangstoken im Header <code>Authorization: Bearer &lt;access&gt;</code>. Anmeldung und Erneuerung über <code>auth/app/</code> sind gedrosselt; bei zu vielen Anfragen antwortet die Schnittstelle mit 429.</p><p><strong>Kartendienste und WebDAV: Benutzername und Passwort.</strong> QGIS Server unter <code>QGIS_DOMAIN</code> und der WebDAV-Zugang unter <code>FILES_DOMAIN</code> gehören nicht zur Schnittstelle, werden aber von ihr geprüft: Caddy fragt vor jeder Anfrage per <code>forward_auth</code> bei <code>/api/v1/auth/qgis-auth/</code> bzw. <code>/api/v1/auth/webdav-auth/</code> an und leitet nur weiter, wenn das Backend zustimmt. Die beiden Endpunkte akzeptieren die Cookies der Weboberfläche oder HTTP-Basic-Authentifizierung, wie sie QGIS sendet. Was das für die Konten bedeutet, beschreibt Abschnitt <a href="./../teil-b-betrieb-admin-qgis/27-qgis-server-und-kartendienste.html#_27-3-authentifizierung-der-dienste">Authentifizierung der Dienste</a>.</p><p>Für die WMS-Ebenen der Karte holt die Weboberfläche über <code>GET /api/v1/wms-sources/access_token/</code> einen Token, der fünf Minuten gilt, und hängt ihn als Parameter <code>token</code> an die Kachelanfragen an den WMS-Proxy. Ein Bildelement der Karte kann keinen Header setzen; der Parameter ersetzt ihn.</p><h2 id="_32-2-aufbau-und-benennung-der-endpunkte" tabindex="-1">32.2 Aufbau und Benennung der Endpunkte <a class="header-anchor" href="#_32-2-aufbau-und-benennung-der-endpunkte" aria-label="Permalink to &quot;32.2 Aufbau und Benennung der Endpunkte&quot;">​</a></h2><p>Die Endpunkte der Fachobjekte sind <code>ViewSet</code>s von Django REST Framework an einem <code>DefaultRouter</code> (<code>backend/apps/api/urls.py</code>) und folgen dessen Muster:</p><table tabindex="0"><thead><tr><th>Anfrage</th><th>Bedeutung</th></tr></thead><tbody><tr><td><code>GET /api/v1/trench/</code></td><td>Liste</td></tr><tr><td><code>POST /api/v1/trench/</code></td><td>anlegen</td></tr><tr><td><code>GET /api/v1/trench/&lt;schlüssel&gt;/</code></td><td>ein Objekt</td></tr><tr><td><code>PUT</code>, <code>PATCH /api/v1/trench/&lt;schlüssel&gt;/</code></td><td>ändern</td></tr><tr><td><code>DELETE /api/v1/trench/&lt;schlüssel&gt;/</code></td><td>löschen</td></tr></tbody></table><p>Der Schlüssel ist bei den meisten Fachobjekten die UUID, bei Trassen die Kennung <code>id_trench</code>, bei den Stammdaten die Nummer. Weil <code>id_trench</code> nur je Projekt eindeutig ist, geben Sie bei Trassen <code>?project=&lt;id&gt;</code> mit an; ohne ihn kann dieselbe Kennung zwei Trassen treffen, und die Anfrage scheitert. Zusatzaktionen hängen am Pfad, etwa <code>GET /api/v1/trench/all/</code> oder <code>GET /api/v1/conduit/&lt;uuid&gt;/trenches/</code>. Die Stammdaten (<code>attributes_*</code>), Projekte, Kennzeichen, Container-Typen, Kostensätze und die Auswahllisten der Leitungsauskunft sind nur lesbar; gepflegt werden sie im Administrationsbereich, siehe Kapitel <a href="./../teil-b-betrieb-admin-qgis/21-projekte-und-stammdaten.html">Projekte und Stammdaten pflegen</a>.</p><p>Eine einheitliche Benennung gibt es nicht. Die Präfixe mischen Unterstriche und Bindestriche, Einzahl und Mehrzahl, und weichen teils von den Tabellennamen ab:</p><ul><li>mit Unterstrich: <code>attributes_cable_type</code>, <code>cable_label</code>, <code>microduct_connection</code>, <code>trench_conduit_connection</code> …</li><li>mit Bindestrich: <code>residential-unit</code>, <code>fiber-splice</code>, <code>feature-files</code>, <code>node-structure</code>, <code>wms-sources</code>, <code>pipeline-records</code> …</li><li>Einzahl: <code>trench</code>, <code>conduit</code>, <code>node</code>, <code>address</code>, <code>cable</code>, <code>fiber</code>; Mehrzahl: <code>projects</code>, <code>flags</code>, <code>logs</code>, <code>wms-sources</code></li></ul><p>Nehmen Sie die Pfade deshalb aus dem Schema, nicht aus einer Regel, siehe Abschnitt <a href="#_32-7-openapi-schema-und-typgenerierung">OpenAPI-Schema und Typgenerierung</a>. Neben dem Router stehen Endpunkte mit eigenem Pfad für alles, was kein einzelnes Objekt ist: die Auswertungen aus Abschnitt <a href="#_32-5-fachliche-endpunkte-routing-faserweg-signalanalyse-storung-wertermittlung-statistik-import-und-export">Fachliche Endpunkte</a>, die Kacheln, die Anmeldung und Hilfsabfragen wie <code>conduits/by-trenches/</code>.</p><h2 id="_32-3-berechtigungsprufung-in-der-schnittstelle" tabindex="-1">32.3 Berechtigungsprüfung in der Schnittstelle <a class="header-anchor" href="#_32-3-berechtigungsprufung-in-der-schnittstelle" aria-label="Permalink to &quot;32.3 Berechtigungsprüfung in der Schnittstelle&quot;">​</a></h2><p>Eine globale Vorgabe für die Rechteprüfung gibt es nicht (<code>DEFAULT_PERMISSION_CLASSES</code> ist nicht gesetzt); jeder Endpunkt nennt seine Prüfung selbst. Es gibt zwei Stufen:</p><ul><li><strong>Angemeldet</strong> (<code>IsAuthenticated</code>) – jedes aktive Konto mit gültigem Token.</li><li><strong>Modellrecht</strong> (<code>RoleBasedPermission</code> in <code>backend/apps/api/permissions.py</code>) – zusätzlich das Recht der Gruppe auf das Modell, aus der Tabelle <code>model_permission</code>.</li></ul><p><code>RoleBasedPermission</code> ordnet jeder HTTP-Methode die Stufe zu, die sie mindestens braucht:</p><table tabindex="0"><thead><tr><th>Methode</th><th>nötige Stufe</th></tr></thead><tbody><tr><td><code>GET</code>, <code>HEAD</code>, <code>OPTIONS</code></td><td><code>view</code></td></tr><tr><td><code>POST</code>, <code>PUT</code>, <code>PATCH</code></td><td><code>edit</code></td></tr><tr><td><code>DELETE</code></td><td><code>full</code></td></tr></tbody></table><p>Das Modell ergibt sich aus dem <code>ViewSet</code>. Gehört ein Konto mehreren Gruppen an, gilt die höchste Stufe; ein Konto ohne Gruppe hat auf kein Modell ein Recht und bekommt 403. Ein Superuser wird nicht geprüft. Was die Stufen für die Verwaltung bedeuten, beschreibt Abschnitt <a href="./../teil-b-betrieb-admin-qgis/19-rollen-und-rechte.html#_19-2-modellrechte-zugriff-je-datenmodell">Modellrechte</a>. Die zusammengeführten Rechte eines Kontos hält jeder Prozess des Backends fünf Minuten vor. Signale leeren diesen Zwischenspeicher, sobald sich <code>model_permission</code>, <code>route_permission</code> oder die Gruppen eines Kontos ändern – aber nur in dem Prozess, der die Änderung speichert; eine geänderte Stufe greift deshalb erst nach bis zu fünf Minuten überall. <code>GET /api/v1/auth/permissions/</code> liefert die zusammengeführten Modell- und Routenrechte des angemeldeten Kontos; die Weboberfläche richtet danach ihre Schaltflächen und ihre Navigationsleiste aus.</p><p>Modellrechte prüfen die <code>ViewSet</code>s der Fachobjekte; welche Objektarten ein Modellrecht haben, listet Abschnitt <a href="./../teil-b-betrieb-admin-qgis/19-rollen-und-rechte.html#_19-2-modellrechte-zugriff-je-datenmodell">Modellrechte</a>.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die Rechte der Gruppen steuern die Bearbeitung über die Endpunkte der Fachobjekte; sie teilen die Daten einer Installation nicht zwischen Konten auf. Vergeben Sie Konten nur an Personen und Stellen, die das Netz der Installation sehen dürfen. Für Daten, die eine Stelle nicht sehen darf, ist eine eigene Installation der sichere Weg.</p></div><p>Routenrechte (<code>route_permission</code>) prüft das Backend nicht; sie steuern nur die Navigation der Weboberfläche, siehe Abschnitt <a href="./../teil-b-betrieb-admin-qgis/19-rollen-und-rechte.html#_19-3-routenrechte-zugriff-je-menupunkt">Routenrechte</a>.</p><h2 id="_32-4-paginierung-filter-und-suche" tabindex="-1">32.4 Paginierung, Filter und Suche <a class="header-anchor" href="#_32-4-paginierung-filter-und-suche" aria-label="Permalink to &quot;32.4 Paginierung, Filter und Suche&quot;">​</a></h2><p><strong>Paginierung.</strong> Auch sie ist nicht global eingestellt, sondern je Endpunkt, und es gibt drei Formen:</p><ul><li>Die meisten Listen der Fachobjekte nutzen <code>CustomPagination</code> (<code>backend/apps/api/pageination.py</code> – der Dateiname ist so geschrieben): 10 Einträge je Seite, mit <code>page_size</code> bis 100, Seite über <code>page</code>. Die Antwort hat die Form von Django REST Framework, <code>count</code>, <code>next</code>, <code>previous</code>, <code>results</code>.</li><li>Die Zusatzaktionen <code>…/all/</code> liefern alle Einträge auf einmal, als einfache Liste. Ausnahmen sind <code>conduit/all/</code> und <code>address/all/</code> sowie die Liste der Leitungsauskünfte: Sie blättern selbst, mit 50 Einträgen je Seite, <code>page_size</code> bis 200, und antworten mit <code>results</code>, <code>count</code>, <code>page</code>, <code>page_size</code>, <code>total_pages</code>. <code>conduit/all/?no_pagination=true</code> liefert alles.</li><li>Listen ohne eigene Paginierung, etwa Wohneinheiten, Fasern, Spleiße oder die Netzknotenstruktur, liefern immer alles.</li></ul><p>Die Form der Antwort hängt also am Endpunkt; prüfen Sie sie im Schema.</p><p><strong>Filter.</strong> Django-Filter ist nicht im Einsatz. Die Endpunkte lesen ihre Filter selbst aus den Abfrageparametern, und welche ein Endpunkt kennt, steht nur in seinem Code und in seiner Beschreibung im Schema. Die häufigsten:</p><ul><li><code>project</code> – die Nummer des Projekts. Fast jede Liste erwartet diesen Parameter; ohne ihn liefern viele Listen die Objekte aller Projekte. Beim Anlegen steht das Projekt im Rumpf; auch die Auswertungen erwarten meist <code>project</code>, nur <code>routing/</code> und <code>fault-simulation/</code> heißen den Wert <code>project_id</code>.</li><li><code>flag</code> – die Nummer eines Kennzeichens.</li><li>Verweise auf übergeordnete Objekte, etwa <code>uuid_conduit</code> für die Mikrorohre eines Rohrs oder <code>node</code> für die Struktur eines Netzknotens.</li></ul><p><strong>Suche.</strong> Der Parameter <code>search</code> gehört zu den Zusatzaktionen <code>…/all/</code>, zu <code>trace-search/</code> und zu den Listen <code>pipeline-records/</code> und <code>logs/</code>. In <code>address/all/</code>, <code>node/all/</code> und <code>area/all/</code> sowie bei Adressen und Netzknoten in <code>trace-search/</code> sucht er mit einer Ähnlichkeitssuche (<code>TrigramWordSimilarity</code> aus <code>pg_trgm</code>, <code>backend/apps/api/search.py</code>). Die Adresssuche zerlegt den Begriff in Wörter und vergleicht sie mit Straße, Ort, Postleitzahl und Ortsteil; Treffer sind nach Ähnlichkeit sortiert. Rohre, Kabel und Leitungsauskünfte suchen dagegen mit einem einfachen Teilstring-Vergleich über mehrere Spalten, Trassen und Wohneinheiten nur in ihrer Kennung.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Bei gleicher Ähnlichkeit ist die Reihenfolge der Treffer nicht festgelegt; zwei gleiche Anfragen können gleich bewertete Treffer in unterschiedlicher Reihenfolge liefern. Wer über die Seiten einer Suche blättert, kann deshalb Treffer doppelt sehen oder verpassen.</p></div><h2 id="_32-5-fachliche-endpunkte-routing-faserweg-signalanalyse-storung-wertermittlung-statistik-import-und-export" tabindex="-1">32.5 Fachliche Endpunkte: Routing, Faserweg, Signalanalyse, Störung, Wertermittlung, Statistik, Import und Export <a class="header-anchor" href="#_32-5-fachliche-endpunkte-routing-faserweg-signalanalyse-storung-wertermittlung-statistik-import-und-export" aria-label="Permalink to &quot;32.5 Fachliche Endpunkte: Routing, Faserweg, Signalanalyse, Störung, Wertermittlung, Statistik, Import und Export&quot;">​</a></h2><p>Die Auswertungen der Weboberfläche sind eigene Endpunkte mit eigenem Pfad:</p><table tabindex="0"><thead><tr><th>Endpunkt</th><th>Zweck</th></tr></thead><tbody><tr><td><code>POST routing/</code></td><td>Weg durch das Trassennetz zwischen zwei Trassen, für die Rohrzuordnung</td></tr><tr><td><code>GET trace-search/</code></td><td>Suche nach Einstiegspunkten für den Faserweg</td></tr><tr><td><code>GET fiber-trace/</code></td><td>Faserweg ab einer Faser, einem Kabel, Netzknoten, einer Adresse oder Wohneinheit</td></tr><tr><td><code>GET fiber-trace/summary/</code></td><td>Kurzfassung des Faserwegs einer Faser</td></tr><tr><td><code>GET signal-analysis/</code></td><td>Signalweg einer Faser ab einer Signalquelle</td></tr><tr><td><code>POST fault-simulation/</code></td><td>betroffene Objekte zu einem Schadenspunkt</td></tr><tr><td><code>POST valuation/calculate/</code></td><td>Wertermittlung eines Projekts oder Gebiets</td></tr><tr><td><code>GET dashboard/statistics/</code></td><td>Kennzahlen des Dashboards</td></tr><tr><td><code>POST spatial/intersects/</code></td><td>Objekte, die eine Geometrie schneiden</td></tr><tr><td><code>GET layer-extent/</code></td><td>Ausdehnung eines Layers</td></tr><tr><td><code>GET config/</code></td><td>Konfiguration für das Frontend, etwa das Koordinatenbezugssystem</td></tr></tbody></table><p>Einige Eigenheiten, die beim Aufruf auffallen:</p><ul><li><code>routing/</code> erwartet <code>project_id</code> und <code>tolerance</code> als Liste mit einem Element (<code>&quot;project_id&quot;: [2]</code>), entgegen dem Schema, das einfache Zahlen angibt: Der Endpunkt liest jeweils das erste Element. Fehlt einer der beiden Werte, scheitert er mit 500.</li><li><code>fiber-trace/</code> nimmt genau einen der Parameter <code>fiber_id</code>, <code>cable_id</code>, <code>node_id</code>, <code>address_id</code>, <code>residential_unit_id</code>. Mit <code>include_geometry</code> liefert er den Weg als Geometrie, <code>geometry_mode</code> und <code>orient_geometry</code> steuern, wie er zusammengesetzt wird.</li><li><code>dashboard/statistics/</code> hält sein Ergebnis bis zu fünf Minuten im Arbeitsspeicher vor. Jeder Worker von gunicorn hat seinen eigenen Stand.</li></ul><p>Import und Export:</p><table tabindex="0"><thead><tr><th>Endpunkt</th><th>Zweck</th></tr></thead><tbody><tr><td><code>GET template/conduit/</code></td><td>Excel-Vorlage für den Rohrimport</td></tr><tr><td><code>POST import/conduit/</code></td><td>Rohrimport aus Excel, siehe Abschnitt <a href="./../teil-a-anwenderhandbuch/10-rohrverwaltung.html#_10-5-excel-import-vorlage-ablauf-fehlermeldungen">Excel-Import</a></td></tr><tr><td><code>GET export/features/</code></td><td>Fachobjekte als GeoJSON</td></tr><tr><td><code>GET schema.gpkg</code></td><td>leeres GeoPackage mit den Tabellen der Netzdaten, siehe Abschnitt <a href="./../teil-b-betrieb-admin-qgis/24-daten-import-und-export.html#_24-2-geopackage-schema-herunterladen">GeoPackage-Schema herunterladen</a></td></tr><tr><td><code>GET node-export/excel/&lt;uuid&gt;/</code></td><td>Struktur eines Netzknotens als Excel-Datei</td></tr><tr><td><code>GET pipeline-records/&lt;uuid&gt;/inquiry-export/</code></td><td>Leitungsauskunft als ZIP-Archiv</td></tr><tr><td><code>GET feature-files/&lt;uuid&gt;/download/</code></td><td>ein Anhang</td></tr></tbody></table><p><strong><code>export/features/</code></strong> ist der Export ohne Gegenstück in der Oberfläche. <code>layers</code> wählt die Objektarten (<code>cable</code>, <code>conduit</code>, <code>node</code>, <code>area</code>, kommagetrennt), <code>project</code> das Projekt; <code>exclude_projects</code> nimmt Projekte aus, wenn <code>project</code> fehlt. Die Antwort enthält je Objektart eine <code>FeatureCollection</code>. Kabel und Rohre haben keine eigene Geometrie; der Export setzt sie aus den Trassen zusammen, in denen sie liegen. Die Eigenschaften enthalten die Stammdaten aufgelöst, also etwa Eigentümer mit Anschrift und Kontaktdaten, nicht nur deren Nummer. Die Koordinaten stehen im Koordinatenbezugssystem der Installation, nicht in WGS 84, wie es GeoJSON-Leser meist annehmen; die Antwort nennt es unter <code>srid</code>. Trassen und Adressen bietet der Export nicht an.</p><p><strong>Proxys.</strong> Zwei Endpunkte reichen Anfragen an Kartendienste weiter: <code>wms-proxy/&lt;uuid&gt;/</code> an eine WMS-Quelle, mit den dort hinterlegten Zugangsdaten, siehe Abschnitt <a href="./../teil-b-betrieb-admin-qgis/27-qgis-server-und-kartendienste.html#_27-5-wms-proxy-und-zwischenspeicher">WMS-Proxy und Zwischenspeicher</a>, und <code>wfs3/&lt;name&gt;/…</code> an die OGC-API-Features-Schnittstelle von QGIS Server, siehe Abschnitt <a href="./../teil-b-betrieb-admin-qgis/27-qgis-server-und-kartendienste.html#_27-2-angebotene-dienste-wms-wfs-wmts-ogc-api-features">Angebotene Dienste</a>.</p><h2 id="_32-6-vektor-tile-endpunkte" tabindex="-1">32.6 Vektor-Tile-Endpunkte <a class="header-anchor" href="#_32-6-vektor-tile-endpunkte" aria-label="Permalink to &quot;32.6 Vektor-Tile-Endpunkte&quot;">​</a></h2><p>Die Netzobjekte der Karte liefert das Backend als Vektorkacheln im Format Mapbox Vector Tile:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/ol_trench_tiles/{z}/{x}/{y}.mvt?project=&lt;id&gt;</span></span>
<span class="line"><span>GET /api/v1/ol_node_tiles/{z}/{x}/{y}.mvt?project=&lt;id&gt;</span></span>
<span class="line"><span>GET /api/v1/ol_address_tiles/{z}/{x}/{y}.mvt?project=&lt;id&gt;</span></span>
<span class="line"><span>GET /api/v1/ol_area_tiles/{z}/{x}/{y}.mvt?project=&lt;id&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Die Kacheln entstehen bei jeder Anfrage in PostGIS, mit <code>ST_TileEnvelope</code>, <code>ST_AsMVTGeom</code> und <code>ST_AsMVT</code> über die Spalte <code>geom_3857</code> (Ausdehnung 4096, Puffer 64). Welche Eigenschaften ein Objekt in der Kachel trägt, legt das SQL im jeweiligen View fest; ein neues Attribut, das in der Karte erscheinen soll, muss dort ergänzt werden, siehe Abschnitt <a href="./36-erweitern-und-mitwirken.html#_36-1-ein-attribut-oder-modell-erganzen">Ein Attribut oder Modell ergänzen</a>.</p><p>Die Antwort hat den Typ <code>application/vnd.mapbox-vector-tile</code>. Eine Kachel ohne Objekte beantwortet der Endpunkt mit 204, auch für ein Projekt, das es nicht gibt; eine Projektnummer, die keine Zahl ist, mit 400. Ohne <code>project</code> enthält die Kachel die Objekte aller Projekte. nginx hält gefüllte Kacheln 30 Sekunden und leere zehn Minuten vor; daher die Verzögerung, mit der Änderungen in der Karte erscheinen, siehe Abschnitt <a href="./../teil-b-betrieb-admin-qgis/26-netzdaten-in-qgis-bearbeiten.html#_26-3-gleichzeitiges-arbeiten-mit-der-weboberflache">Gleichzeitiges Arbeiten mit der Weboberfläche</a>.</p><p>Die Hintergrundkarte kommt nicht aus diesen Endpunkten, sondern vom Kachelserver unter <code>TILE_SERVER_DOMAIN</code>, siehe Abschnitt <a href="./35-bereitstellung-und-infrastruktur.html#_35-6-kachelserver">Kachelserver</a>.</p><h2 id="_32-7-openapi-schema-und-typgenerierung" tabindex="-1">32.7 OpenAPI-Schema und Typgenerierung <a class="header-anchor" href="#_32-7-openapi-schema-und-typgenerierung" aria-label="Permalink to &quot;32.7 OpenAPI-Schema und Typgenerierung&quot;">​</a></h2><p>Das Schema der Schnittstelle erzeugt drf-spectacular. Es liegt in zwei Formen vor:</p><ul><li><strong><code>backend/schema.yml</code></strong> im Repository, OpenAPI 3.0. Aus ihr erzeugt <code>npm run generate:types</code> im Frontend mit openapi-typescript die Typen in <code>frontend/src/lib/types/api.d.ts</code>.</li><li><strong>Zur Laufzeit</strong> unter <code>/api/v1/schema/</code>, mit einer Swagger-Oberfläche unter <code>/api/v1/docs/</code>. Beide gibt es nur bei <code>DEBUG=True</code>, also in der Entwicklungsumgebung aus Kapitel <a href="./30-entwicklungsumgebung.html">Entwicklungsumgebung</a>; eine Installation im Betrieb beantwortet beide Pfade mit 404. Ebenso nur mit <code>DEBUG</code> ist die im Browser bedienbare Darstellung von Django REST Framework eingeschaltet.</li></ul><p>Nach einer Änderung an Modellen, Serialisierern oder Views erneuern Sie beide Dateien:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spectacular</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema.yml</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../frontend</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generate:types</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Die CI des Frontends erzeugt <code>api.d.ts</code> aus der eingecheckten <code>schema.yml</code> neu und schlägt fehl, wenn sich die Datei dabei ändert, siehe Abschnitt <a href="./34-qualitaetssicherung.html#_34-5-ci-pipeline">CI-Pipeline</a>. Ob <code>schema.yml</code> selbst zum Code passt, prüft sie nicht.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die Beschreibungstexte im Schema hängen von der Sprache ab, in der <code>spectacular</code> läuft – Texte von Django REST Framework und die Namen der Modelle werden übersetzt. Eine neu erzeugte <code>schema.yml</code> unterscheidet sich deshalb auch ohne Änderung am Code in Hunderten von Zeilen von der eingecheckten. Prüfen Sie den Diff vor dem Commit und übernehmen Sie nur, was zur eigenen Änderung gehört.</p></div><p>Das Schema ist so gut wie die Annotationen der Views. Viele eigene Endpunkte beschreiben ihre Parameter nur im Docstring, und <code>spectacular</code> meldet beim Erzeugen zahlreiche Warnungen zu Endpunkten, deren Antwort es nicht ableiten kann. Für diese Endpunkte ist der Code die verlässliche Quelle.</p><h2 id="_32-8-fehlerbehandlung-und-statuscodes" tabindex="-1">32.8 Fehlerbehandlung und Statuscodes <a class="header-anchor" href="#_32-8-fehlerbehandlung-und-statuscodes" aria-label="Permalink to &quot;32.8 Fehlerbehandlung und Statuscodes&quot;">​</a></h2><p>Eine eigene Fehlerbehandlung (<code>EXCEPTION_HANDLER</code>) gibt es nicht. Die Form einer Fehlerantwort hängt deshalb davon ab, wo der Fehler entsteht:</p><ul><li><strong>Django REST Framework</strong> – Anmeldung, Rechte, nicht gefundene Objekte, Drosselung: <code>{&quot;detail&quot;: &quot;…&quot;}</code>.</li><li><strong>Serialisierer</strong> – ungültige Eingaben beim Anlegen oder Ändern: ein Objekt mit dem Feldnamen als Schlüssel und einer Liste von Meldungen je Feld, <code>{&quot;name&quot;: [&quot;…&quot;]}</code>.</li><li><strong>Eigene Endpunkte</strong> – fehlende Parameter, fachliche Fehler: meist <code>{&quot;error&quot;: &quot;…&quot;}</code>, vereinzelt auch <code>{&quot;detail&quot;: &quot;…&quot;}</code>.</li></ul><p>Ein Programm, das die Schnittstelle nutzt, prüft deshalb beide Schlüssel. Die Meldungen sind teils übersetzt, teils englisch; werten Sie den Statuscode aus, nicht den Text.</p><table tabindex="0"><thead><tr><th>Code</th><th>Bedeutung</th></tr></thead><tbody><tr><td>200, 201</td><td>Erfolg, angelegt</td></tr><tr><td>204</td><td>gelöscht; bei Kacheln: keine Objekte in der Kachel</td></tr><tr><td>400</td><td>Parameter fehlt oder Eingabe ungültig</td></tr><tr><td>401</td><td>nicht angemeldet oder Token abgelaufen – erneuern und wiederholen</td></tr><tr><td>403</td><td>angemeldet, aber ohne das nötige Modellrecht</td></tr><tr><td>404</td><td>Objekt oder Pfad nicht vorhanden</td></tr><tr><td>429</td><td>zu viele Anmelde- oder Erneuerungsanfragen über <code>auth/app/</code></td></tr><tr><td>500</td><td>Fehler im Backend; die Meldung steht in den Protokollen, siehe Abschnitt <a href="./../teil-b-betrieb-admin-qgis/28-betrieb-der-instanz.html#_28-5-protokolle-auswerten">Protokolle auswerten</a></td></tr></tbody></table><p>Fehler, die die Datenbank selbst auslöst – ein Trigger, der eine ungültige Geometrie zurückweist, oder ein Netzknoten, der sich wegen seiner Kabel nicht löschen lässt –, kommen bei den meisten Endpunkten als 500 an, nicht als 400. Ihre Meldung steht in den Protokollen; was die Trigger prüfen, beschreibt Abschnitt <a href="./31-datenmodell-des-backends.html#_31-9-migrationen-datenbank-trigger-und-signale">Migrationen, Datenbank-Trigger und Signale</a>.</p>`,67)])])}const p=t(r,[["render",a]]);export{g as __pageData,p as default};
